/* PsychLogic — Foundational Mock 1 question bank.
   Edit/replace questions here. Each item:
   { id, question, options[4], correctAnswer(0-3), subject, subtopic, explanation, difficulty } */
window.MOCK_QUESTIONS = [{"id": 1, "question": "A baby may understand much more language than they are able to express. For example, the baby may understand a long instruction but respond with only one or two words. What is this phenomenon called?", "options": ["Child-directed speech", "Receptive–productive language lag", "Telegraphic speech", "Language Acquisition Device"], "correctAnswer": 1, "subject": "Developmental Psychology", "subtopic": "", "explanation": "This phenomenon describes when infants and toddlers comprehend significantly more language than they can verbally express. Research shows babies can understand complex instructions and recognize many object names by six months, yet may only produce one or two words in response. This gap between receptive (understanding) and productive/expressive (speaking) language is normal in early development.", "difficulty": "Medium"}, {"id": 2, "question": "Which theory says that cognitive development is mainly shaped by guided participation and cultural tools?", "options": ["Piagetian constructivism", "Behaviorism", "Sociocultural theory", "Psychoanalytic theory"], "correctAnswer": 2, "subject": "History & Schools of Psychology", "subtopic": "", "explanation": "Lev Vygotsky's sociocultural theory emphasizes that cognitive development occurs through social interaction, guided participation with more knowledgeable others, and the use of cultural tools like language. Children learn by engaging in collaborative activities within their cultural context, rather than through individual discovery alone. This contrasts with Piaget's constructivism which focuses more on individual exploration.", "difficulty": "Medium"}, {"id": 3, "question": "In Margaret Mahler’s theory, separation–individuation refers to:", "options": ["Formation of superego", "Differentiation from primary caregiver", "Language acquisition", "Moral internalization"], "correctAnswer": 1, "subject": "Personality & Psychoanalysis", "subtopic": "", "explanation": "Margaret Mahler's separation-individuation theory describes how infants develop a sense of individual identity separate from their primary caregiver (typically the mother) between 5-24 months. The process includes sub-stages like differentiation/hatching where the baby begins recognizing the caregiver as a separate person. This is not about superego formation or moral development. openlab.", "difficulty": "Easy"}, {"id": 4, "question": "A child can understand conservation of volume but has trouble with hypothetical reasoning. This pattern fits which Piaget stage?", "options": ["Preoperational stage", "Concrete operational stage", "Formal operational stage", "Sensorimotor stage"], "correctAnswer": 1, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Children in Piaget's concrete operational stage (ages 7-11) can understand conservation of volume, mass, and number, but struggle with abstract hypothetical reasoning. They think logically about concrete, tangible events and situations they can observe directly. Hypothetical-deductive reasoning develops later in the formal operational stage during adolescence.", "difficulty": "Medium"}, {"id": 5, "question": "A child who is adaptable, has regular habits, and usually shows a positive mood fits which temperament type (Thomas &amp; Chess)?", "options": ["Difficult", "Slow-to-warm", "Easy", "Reactive"], "correctAnswer": 2, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Thomas and Chess identified three temperament types. Easy children (about 40% of sample) show regular biological rhythms, positive mood, adaptability to new situations, and moderate emotional reactions. Difficult children have irregular habits and negative reactions; slow-to-warm children are less active and need time to adapt to novelty.", "difficulty": "Medium"}, {"id": 6, "question": "The ability to understand another person’s emotional state is most closely related to:", "options": ["Empathy", "Projection", "Sublimation", "Displacement"], "correctAnswer": 0, "subject": "Social Psychology", "subtopic": "", "explanation": "Empathy is the ability to understand and share another person's emotional state from their perspective, involving both cognitive understanding and emotional resonance. Projection, sublimation, and displacement are defense mechanisms that involve attributing one's own feelings to others or redirecting impulses, not understanding others' emotions.", "difficulty": "Medium"}, {"id": 7, "question": "According to Erik Erikson, if an adolescent does not successfully resolve the main psychosocial crisis, they are most likely to develop:", "options": ["Role fixation", "Identity diffusion", "Inferiority complex", "Basic mistrust"], "correctAnswer": 1, "subject": "Social Psychology", "subtopic": "", "explanation": "Erik Erikson's fifth psychosocial stage (Identity vs. Role Confusion) occurs during adolescence. Failure to resolve this crisis results in identity diffusion—a lack of clear direction, commitment, or coherent sense of self. Adolescents in diffusion have neither explored identity options nor committed to values, beliefs, or life directions.", "difficulty": "Medium"}, {"id": 8, "question": "Which behavior best shows fine motor coordination?", "options": ["Climbing stairs", "Throwing a ball", "Using a pencil to draw shapes", "Balancing on one foot"], "correctAnswer": 2, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Fine motor coordination involves small muscle movements of hands, fingers, and wrists for precise tasks like drawing, writing, cutting, and manipulating small objects. Climbing stairs, throwing balls, and balancing involve gross motor skills using large muscle groups of arms, legs, and trunk for whole-body movements.", "difficulty": "Medium"}, {"id": 9, "question": "A child consistently avoids interacting with peers, this most directly suggests a problem in:", "options": ["Motor maturation", "Social competence", "Language acquisition", "Executive functioning"], "correctAnswer": 1, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Consistent avoidance of peer interaction directly indicates problems with social competence—the ability to interact effectively with others, form relationships, and navigate social situations. While other domains may contribute, social competence is most directly implicated. Motor maturation, language, and executive functioning affect different behavioral domains.", "difficulty": "Medium"}, {"id": 10, "question": "The idea that early bonds influence later emotional regulation and relationships comes mainly from:", "options": ["Psychoanalysis", "Behaviorism", "Attachment theory", "Humanism"], "correctAnswer": 2, "subject": "Social Psychology", "subtopic": "", "explanation": "John Bowlby's attachment theory proposes that early emotional bonds with caregivers form internal working models that influence later emotional regulation, relationship patterns, and psychological development throughout life. Secure attachment in childhood predicts better social competence and wellbeing across the lifespan. simplypsychology+3", "difficulty": "Medium"}, {"id": 11, "question": "According to Piaget, the ability to think logically about concrete events develops during the:", "options": ["Sensorimotor stage", "Preoperational stage", "Concrete operational stage", "Formal operational stage"], "correctAnswer": 2, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Piaget's concrete operational stage (ages 7-11) is characterized by the ability to think logically about concrete events, understand conservation, reversibility, classification, and seriation. Children can perform mental operations on tangible objects but not yet on abstract hypothetical situations, which requires formal operational thinking. simplypsychology+3", "difficulty": "Medium"}, {"id": 12, "question": "According to psychodynamic theory, a person may respond to the world based on perspectives and relationship patterns learned from important people during their earlier developmental experiences. What is this concept called?", "options": ["Object permanence theory", "Distorted perspective theory", "Object-relations theory", "Ego defence theory"], "correctAnswer": 2, "subject": "Personality & Psychoanalysis", "subtopic": "", "explanation": "Object-relations theory, a psychodynamic approach, proposes that people respond to the world based on internalized representations (objects) of important early relationships. These mental representations of caregivers and relationship patterns learned in childhood shape how individuals perceive and interact with others throughout life. openlab.bmcc.cuny+3", "difficulty": "Medium"}, {"id": 13, "question": "The “vocabulary spurt” (rapid word learning) is most closely linked to:", "options": ["Early infancy", "Transition to symbolic thinking", "Toddlerhood language acceleration", "Pre-adolescent reasoning"], "correctAnswer": 2, "subject": "Developmental Psychology", "subtopic": "", "explanation": "The vocabulary spurt (naming explosion) occurs typically between 18-24 months during toddlerhood, when children shift from learning 1-2 words per week to acquiring 5-10+ new words daily. This rapid word learning coincides with developments in symbolic thinking and marks a dramatic acceleration in language acquisition. bbc+4", "difficulty": "Medium"}, {"id": 14, "question": "In Kohlberg’s theory, morality based on avoiding punishment and obtaining rewards belongs to:", "options": ["Preconventional morality", "Conventional morality", "Postconventional morality", "Autonomous morality"], "correctAnswer": 0, "subject": "Social Psychology", "subtopic": "", "explanation": "Kohlberg's preconventional level (typically until age 8-9) includes Stage 1 (obedience/punishment orientation) and Stage 2 (instrumental purpose/reward orientation). Children at this level make moral decisions based on avoiding punishment and obtaining rewards rather than internalized moral principles or social conventions. simplypsychology+4", "difficulty": "Medium"}, {"id": 15, "question": "The ideas of “imaginary audience” and “personal fable” describe:", "options": ["Egocentrism in adolescence", "Moral reasoning deficits", "Language delays", "Attachment insecurity"], "correctAnswer": 0, "subject": "Social Psychology", "subtopic": "", "explanation": "David Elkind identified the imaginary audience (belief that others constantly watch and judge) and personal fable (belief in personal uniqueness and invincibility) as two components of adolescent egocentrism. These cognitive distortions reflect teenagers' difficulty distinguishing their own perspective from others' during this developmental period.", "difficulty": "Medium"}, {"id": 16, "question": "The “Zone of Proximal Development” (ZPD) refers to:", "options": ["Tasks a child can perform independently", "Tasks beyond cognitive ability", "Gap between independent and assisted performance", "Fixed intelligence potential"], "correctAnswer": 2, "subject": "Intelligence", "subtopic": "", "explanation": "Vygotsky's Zone of Proximal Development (ZPD) refers to the difference between what a learner can do independently and what they can achieve with guidance from a more knowledgeable other. It represents the potential for learning through scaffolding and guided participation within the sociocultural context.", "difficulty": "Easy"}, {"id": 17, "question": "Which attachment style is characterized by distress upon separation and difficulty being comforted when the caregiver returns?", "options": ["Secure", "Avoidant", "Resistant/ambivalent", "Disorganized"], "correctAnswer": 2, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Resistant (ambivalent) attachment is characterized by intense distress upon caregiver separation and difficulty being comforted when the caregiver returns. Children may show anger or resistance toward the caregiver despite seeking proximity. Secure children are easily comforted; avoidant children show minimal distress; disorganized children show contradictory behaviors.", "difficulty": "Medium"}, {"id": 18, "question": "Theory of Mind is best shown when a child can:", "options": ["Understand object permanence", "Recognize false beliefs in others", "Solve conservation tasks", "Use abstract reasoning"], "correctAnswer": 1, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Theory of Mind is best demonstrated when children understand that others can hold beliefs different from their own and from reality (false belief understanding). Standard tasks like Sally-Anne test assess this ability, which typically emerges around ages 4-5 years. This shows understanding that mental states guide behavior.", "difficulty": "Medium"}, {"id": 19, "question": "The ability to mentally reverse an action (reversibility) is a key feature of:", "options": ["Preoperational thinking", "Concrete operational reasoning", "Sensorimotor intelligence", "Formal abstract thought"], "correctAnswer": 1, "subject": "Intelligence", "subtopic": "", "explanation": "Reversibility—the ability to mentally undo actions or operations—is a key achievement of Piaget's concrete operational stage. Children understand that pouring liquid back into the original glass restores the original amount, or that 5+3=8 means 8-3=5. This logical skill doesn't emerge in preoperational or sensorimotor stages. simplypsychology+3", "difficulty": "Medium"}, {"id": 20, "question": "A persistent fear of being negatively evaluated or embarrassed in social situations is characteristic of:", "options": ["Agoraphobia", "Social anxiety disorder", "Separation anxiety disorder", "Specific phobia"], "correctAnswer": 1, "subject": "Clinical & Abnormal Psychology", "subtopic": "", "explanation": "Social anxiety disorder (social phobia) is characterized by persistent, intense fear of negative evaluation, embarrassment, or humiliation in social situations. Individuals worry excessively about criticism, rejection, or being judged negatively, leading to avoidance of social interactions. This differs from agoraphobia (fear of situations where escape is difficult) and specific phobias. pmc.ncbi.nlm.nih+3", "difficulty": "Medium"}, {"id": 21, "question": "Who made the first attempt to standardize mental tests in India, according to this commonly used exam question?", "options": ["Dr. S. M. Mohsin", "V. V. Kamat", "Dr. C. H. Rice", "Dr. Sohan Lal"], "correctAnswer": 2, "subject": "Indian Psychology & Law", "subtopic": "", "explanation": "Dr. C. H. Rice made the first systematic attempt to standardize mental tests in India by adapting Binet's intelligence test in Urdu and Punjabi during the 1930s. S. M. Mohsin later developed an intelligence test in Hindi, and Mahalanobis standardized Binet's test in Bengali around the same period.", "difficulty": "Easy"}, {"id": 22, "question": "The tendency to perceive objects that are close together as belonging to the same group is the Gestalt principle of:", "options": ["Similarity", "Closure", "Proximity", "Continuity"], "correctAnswer": 2, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "The Gestalt law of proximity states that objects or shapes positioned close to one another are perceived as forming groups or belonging together, regardless of their actual shapes, sizes, or characteristics. This principle explains how we naturally organize visual stimuli into meaningful patterns based on spatial nearness.", "difficulty": "Medium"}, {"id": 23, "question": "The tendency to perceive an object as remaining the same despite changes in its sensory appearance is called:", "options": ["Perceptual constancy", "Figure-ground organization", "Closure", "Proximity"], "correctAnswer": 0, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Perceptual constancy is the tendency to perceive objects as maintaining stable properties (size, shape, color, brightness) despite changes in sensory input due to viewing angle, distance, or lighting conditions. This allows us to recognize a white mug as white under both bright and dim illumination, maintaining stable perception.", "difficulty": "Easy"}, {"id": 24, "question": "Which lobe of the brain is primarily involved in processing visual information?", "options": ["Frontal lobe", "Temporal lobe", "Parietal lobe", "Occipital lobe"], "correctAnswer": 3, "subject": "Biological Psychology", "subtopic": "", "explanation": "The occipital lobe, located at the back of the brain, is the primary visual processing center containing the primary visual cortex (V1/Brodmann area 17). It receives and interprets visual signals from the eyes, processing features like edges, orientation, color, motion, and spatial location. Other lobes handle different functions.", "difficulty": "Medium"}, {"id": 25, "question": "Theory of Mind is best shown when a child can:", "options": ["Understand object permanence", "Recognize false beliefs in others", "Solve conservation tasks", "Use abstract reasoning"], "correctAnswer": 1, "subject": "Developmental Psychology", "subtopic": "", "explanation": "(Duplicate of Q18) Theory of Mind is best demonstrated when children understand that others can hold beliefs different from their own and from reality (false belief understanding). Standard tasks like Sally-Anne test assess this ability, which typically emerges around ages 4-5 years. This shows understanding that mental states guide behavior.", "difficulty": "Medium"}, {"id": 26, "question": "The ability to mentally reverse an action (reversibility) is a key feature of:", "options": ["Preoperational thinking", "Concrete operational reasoning", "Sensorimotor intelligence", "Formal abstract thought"], "correctAnswer": 1, "subject": "Intelligence", "subtopic": "", "explanation": "(Duplicate of Q19) Reversibility—the ability to mentally undo actions or operations—is a key achievement of Piaget's concrete operational stage. Children understand that pouring liquid back into the original glass restores the original amount, or that 5+3=8 means 8-3=5. This logical skill doesn't emerge in preoperational or sensorimotor stages.", "difficulty": "Medium"}, {"id": 27, "question": "While walking through a crowded college corridor, Rahul briefly noticed the clothes worn by several students. The visual information was retained for only a very brief period before fading. This type of memory is known as:", "options": ["Short-term memory", "Iconic memory", "Long-term memory", "Echoic memory"], "correctAnswer": 1, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Iconic memory is visual sensory memory that retains visual information for a very brief period (150-500 milliseconds) after stimulus offset. When Rahul briefly noticed clothes in the corridor and the visual information faded rapidly, this exemplifies iconic memory—the fleeting visual sensory register that provides a momentary snapshot of the visual scene.", "difficulty": "Medium"}, {"id": 28, "question": "Which philosopher argued that memories are residual traces of previous sensory impressions?", "options": ["Thomas Hobbes", "René Descartes", "Benedict de Spinoza", "John Locke"], "correctAnswer": 0, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Thomas Hobbes argued that memories are residual traces (decaying sense) of previous sensory impressions. He proposed that all mental content originates from sensation, and memories are weakened sensory experiences that persist after the original stimulus ends. This empiricist view influenced later associationist theories of memory and learning.", "difficulty": "Medium"}, {"id": 29, "question": "A child develops fear of a particular dog after being bitten. Later, the child begins to fear other dogs as well. This best illustrates:", "options": ["Generalization", "Punishment", "Negative reinforcement", "Law of Exercise"], "correctAnswer": 0, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Stimulus generalization occurs when a conditioned response (fear) elicited by one stimulus (the biting dog) spreads to similar stimuli (other dogs). After being bitten by one dog, the child's fear response generalizes to the broader category of dogs. This differs from discrimination, where responses remain specific to the original conditioned stimulus.", "difficulty": "Medium"}, {"id": 30, "question": "Which of the following best represents Freud&#x27;s concept of the unconscious?", "options": ["Mental processes that are always consciously accessible", "Thoughts and wishes that can operate outside conscious awareness", "Behaviours that occur only in response to external stimuli", "Knowledge acquired exclusively through sensory experience"], "correctAnswer": 1, "subject": "Personality & Psychoanalysis", "subtopic": "", "explanation": "Freud's unconscious contains thoughts, wishes, memories, feelings, and instinctual drives that operate outside conscious awareness yet powerfully influence behavior, emotions, and decisions. The unconscious holds repressed or unacceptable content that remains inaccessible to consciousness without therapeutic intervention like free association or dream analysis.", "difficulty": "Medium"}, {"id": 31, "question": "Which of the following groups consists entirely of philosophers or physicians identified in the material as pre-Socratic thinkers?", "options": ["Plato, Aristotle, Galen, Cicero", "Alcmaeon, Protagoras, Democritus, Hippocrates", "Augustine, Avicenna, Aristotle, Plato", "Freud, Brentano, Maslow, Hippocrates"], "correctAnswer": 1, "subject": "Humanistic Psychology", "subtopic": "", "explanation": "Pre-Socratic philosophers (6th-5th century BCE) preceded or were contemporaries of Socrates. Alcmaeon (medical theorist), Protagoras (sophist), Democritus (atomist), and Hippocrates (physician) all belong to this period. Plato, Aristotle, Augustine, Avicenna, and Freud are from later periods and not pre-Socratic thinkers.", "difficulty": "Medium"}, {"id": 32, "question": "In Wundt&#x27;s laboratory, collaborators were specifically trained to:", "options": ["Diagnose mental disorders using clinical interviews", "Interpret unconscious conflicts", "Report their own sensory experiences following physical stimulation", "Measure personality traits using standardized tests"], "correctAnswer": 2, "subject": "Clinical & Abnormal Psychology", "subtopic": "", "explanation": "In Wundt's Leipzig laboratory (established 1879), collaborators underwent extensive training in introspection to report their immediate conscious experiences in response to standardized stimuli like lights, sounds, or weights. This highly controlled method aimed to analyze consciousness into basic elements through trained self-observation.", "difficulty": "Medium"}, {"id": 33, "question": "A person experiences an unacceptable impulse but cannot consciously recognize the impulse itself. However, the impulse later appears indirectly as a psychological symptom. Which Freudian concept best explains this process?", "options": ["Object permanence", "Repression and disguised expression of unconscious impulses", "Accommodation", "Regression toward the mean"], "correctAnswer": 1, "subject": "Personality & Psychoanalysis", "subtopic": "", "explanation": "Freud proposed that unacceptable impulses are prevented from entering consciousness through repression, yet these unconscious contents continue to influence behavior and may emerge indirectly as psychological symptoms, dreams, slips, or neurotic behaviors. The impulse remains unconscious but finds disguised expression through symptoms.", "difficulty": "Medium"}, {"id": 34, "question": "Classical conditioning is also known as:", "options": ["Instrumental conditioning", "Operant conditioning", "Associative or Pavlovian conditioning", "Observational learning"], "correctAnswer": 2, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Classical conditioning, discovered by Ivan Pavlov, is also called associative conditioning or Pavlovian conditioning. It involves learning associations between stimuli, where a neutral stimulus becomes associated with an unconditioned stimulus to elicit a conditioned response. This differs from operant/instrumental conditioning which involves behavior-consequence associations.", "difficulty": "Medium"}, {"id": 35, "question": "A researcher claims that a person&#x27;s intelligence can be inferred accurately by examining the shape and size of different regions of the skull. This claim is most consistent with:", "options": ["Functionalism", "Structuralism", "Phrenology", "Pragmatism"], "correctAnswer": 2, "subject": "Biological Psychology", "subtopic": "", "explanation": "Phrenology, founded by Franz Joseph Gall, claimed that intelligence, personality traits, and mental abilities could be determined by examining the shape, size, and contours of different skull regions. This pseudoscience proposed that brain areas correspond to specific faculties and that skull morphology reflects brain development.", "difficulty": "Medium"}, {"id": 36, "question": "Descartes&#x27; famous statement Cogito ergo sum (&quot;I think, therefore I am&quot;) primarily illustrates his emphasis on:", "options": ["Sensory experience as the only source of knowledge", "Thinking as evidence of one's existence", "Memory as the basis of identity", "Behaviour as the basis of consciousness"], "correctAnswer": 1, "subject": "Indian Psychology & Law", "subtopic": "", "explanation": "Descartes' \"Cogito, ergo sum\" (I think, therefore I am) establishes thinking as indubitable proof of existence. Even if all sensory experience is deceptive, the very act of doubting or thinking guarantees the thinker's existence as a thinking entity. This became the first principle of his philosophy and foundation for certain knowledge.", "difficulty": "Medium"}, {"id": 37, "question": "Phrenology was founded by:", "options": ["Gustav Fechner", "Franz Joseph Gall", "Hermann Helmholtz", "Ernst Weber"], "correctAnswer": 1, "subject": "Biological Psychology", "subtopic": "", "explanation": "Phrenology was founded by German physician Franz Joseph Gall (1758-1828), who proposed that the brain consists of multiple distinct organs corresponding to different mental faculties, and that skull shape reflects the development of these brain areas. Though now discredited, phrenology influenced early localization theories.", "difficulty": "Easy"}, {"id": 38, "question": "Pavlov&#x27;s famous conditioning research began with observations of:", "options": ["Dogs salivating before food was presented", "Cats escaping puzzle boxes", "Children developing phobias", "Pigeons pressing levers"], "correctAnswer": 0, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Pavlov's classical conditioning research began with observations that dogs in his digestion studies started salivating before food was actually presented—responding to cues associated with feeding like the experimenter's footsteps or laboratory apparatus. This led him to investigate conditioned reflexes systematically.", "difficulty": "Medium"}, {"id": 39, "question": "Which situation best illustrates positive reinforcement in the behavioural framework described in the material?", "options": ["A behaviour decreases because it is punished", "A behaviour increases because it is followed by a reward", "A behaviour disappears because it is ignored", "A behaviour changes because an unconscious conflict is resolved"], "correctAnswer": 1, "subject": "Personality & Psychoanalysis", "subtopic": "", "explanation": "Positive reinforcement occurs when a behavior increases in frequency because it is followed by the presentation of a rewarding stimulus. The reward strengthens the behavior, making it more likely to occur again. This differs from punishment (which decreases behavior) and negative reinforcement (removal of aversive stimulus).", "difficulty": "Medium"}, {"id": 40, "question": "Which modern perspective described in the material differs most clearly from Aristotle&#x27;s teleological explanation of human reasoning?", "options": ["Darwin's theory of natural selection", "Maslow's theory of self-actualization", "Freud's structural theory", "Plato's theory of Forms"], "correctAnswer": 0, "subject": "Humanistic Psychology", "subtopic": "", "explanation": "Aristotle's teleological explanations proposed that human reasoning and behavior serve predetermined purposes or final causes. Darwin's theory of natural selection differs fundamentally by explaining traits and behaviors through evolutionary adaptation and survival value without predetermined purpose, emphasizing variation and environmental selection.", "difficulty": "Medium"}, {"id": 41, "question": "Which psychologist is most directly associated with the Law of Effect?", "options": ["Edward Thorndike", "Ivan Pavlov", "John Watson", "B. F. Skinner"], "correctAnswer": 0, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Edward Thorndike formulated the Law of Effect, stating that behaviors followed by satisfying consequences are strengthened (more likely to recur), while behaviors followed by unpleasant consequences are weakened. This principle became foundational for operant conditioning and behaviorist learning theory developed later by Skinner.", "difficulty": "Easy"}, {"id": 42, "question": "Folk psychology is best characterized in the passage as:", "options": ["A formal experimental method used in psychological laboratories", "Common-sense psychological ideas transmitted through sayings, aphorisms, and proverbs", "A medical theory based on bodily humors", "A philosophical system developed exclusively by Renaissance thinkers"], "correctAnswer": 1, "subject": "History & Schools of Psychology", "subtopic": "", "explanation": "Folk psychology refers to everyday, common-sense psychological understanding transmitted culturally through proverbs, sayings, aphorisms, and shared beliefs about human behavior and mental processes. It contrasts with formal scientific psychology and represents intuitive theories people use to explain behavior.", "difficulty": "Medium"}, {"id": 43, "question": "Freud proposed that unacceptable wishes or impulses are prevented from entering conscious awareness primarily through:", "options": ["Sublimation", "Repression", "Accommodation", "Extinction"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Freud proposed that repression is the primary defense mechanism preventing unacceptable wishes, impulses, and memories from entering conscious awareness. These repressed contents remain in the unconscious yet continue to influence behavior, emotions, and may emerge as symptoms, dreams, or Freudian slips.", "difficulty": "Medium"}, {"id": 44, "question": "Which of the following correctly matches the philosopher with the concept attributed to him in the passage?", "options": ["Descartes — associative memory", "Spinoza — cognitive appraisal influencing emotional response", "Hobbes — sensation and reflection", "Locke — Cartesian dualism"], "correctAnswer": 1, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Benedict de Spinoza proposed that emotions are influenced by cognitive appraisal—how we think about situations affects our emotional responses. This anticipates modern cognitive theories of emotion. Descartes proposed mind-body dualism, Hobbes emphasized sensation and reflection, and Locke proposed empiricist ideas about experience.", "difficulty": "Hard"}, {"id": 45, "question": "Piaget&#x27;s distinction between assimilation and accommodation is best captured by which statement?", "options": ["Assimilation modifies an existing schema, whereas accommodation preserves it", "Assimilation fits new information into an existing schema, whereas accommodation modifies the schema", "Both terms refer to reinforcement of behaviour", "Both terms refer to unconscious conflict resolution"], "correctAnswer": 1, "subject": "Personality & Psychoanalysis", "subtopic": "", "explanation": "Piaget distinguished assimilation (incorporating new experiences into existing cognitive schemas without changing them) from accommodation (modifying existing schemas or creating new ones when new information doesn't fit). Both processes work together in cognitive adaptation and development.", "difficulty": "Medium"}, {"id": 46, "question": "A child encounters a differently shaped rattle and must modify an existing grasping pattern to successfully manipulate it. This illustrates:", "options": ["Assimilation", "Accommodation", "Fixation", "Reinforcement"], "correctAnswer": 1, "subject": "Developmental Psychology", "subtopic": "", "explanation": "When a child must modify an existing grasping pattern (schema) to successfully manipulate a differently shaped rattle, this illustrates accommodation—adjusting cognitive structures to incorporate new experiences that don't fit existing schemas. Assimilation would involve using the existing grasp without modification.", "difficulty": "Medium"}, {"id": 47, "question": "In classical conditioning, an unconditioned stimulus produces a response that is:", "options": ["Learned", "Innate or unlearned", "Reinforced", "Voluntary"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "In classical conditioning, an unconditioned stimulus (UCS) naturally and automatically triggers an unconditioned response (UCR) without prior learning. The response is innate, reflexive, or unlearned (e.g., food causing salivation, loud noise causing startle). This contrasts with conditioned responses which are learned through association.", "difficulty": "Medium"}, {"id": 48, "question": "India’s first comprehensive legislation addressing the rights and rehabilitation of persons with disabilities was enacted in:", "options": ["1986", "1995", "2001", "2007"], "correctAnswer": 1, "subject": "Indian Psychology & Law", "subtopic": "", "explanation": "India's first comprehensive disability rights legislation, The Persons with Disabilities (Equal Opportunities, Protection of Rights and Full Participation) Act, was enacted in 1995 and came into force on February 7, 1996. This landmark law addressed rights, rehabilitation, and full participation of persons with disabilities.", "difficulty": "Easy"}, {"id": 49, "question": "Which milestone marked the formal beginning of experimental psychology as an independent scientific discipline?", "options": ["Publication of The Interpretation of Dreams", "Establishment of the University of Leipzig laboratory in 1879", "Formation of the American Psychological Association", "Publication of the first DSM"], "correctAnswer": 1, "subject": "History & Schools of Psychology", "subtopic": "", "explanation": "Wilhelm Wundt's establishment of the first experimental psychology laboratory at the University of Leipzig in 1879 marked the formal beginning of psychology as an independent scientific discipline separate from philosophy and physiology. This event is widely recognized as the birth of modern scientific psychology.", "difficulty": "Medium"}, {"id": 50, "question": "Repeated passage of feces into inappropriate places, such as clothing or the floor, by a child who is developmentally old enough for bowel control is known as:", "options": ["Encopresis", "Enuresis", "Coprolalia", "Fecal incontinence disorder"], "correctAnswer": 0, "subject": "Clinical & Abnormal Psychology", "subtopic": "", "explanation": "Encopresis is the repeated passage of feces into inappropriate places (clothing, floor) by a child developmentally old enough for bowel control (typically age 4+). It may be involuntary or intentional. Enuresis refers to involuntary urination; coprolalia is involuntary utterance of obscenities associated with Tourette's.", "difficulty": "Medium"}, {"id": 51, "question": "The Mental Healthcare Act that emphasizes the rights of persons with mental illness and decriminalizes suicide attempts was passed in:", "options": ["2014", "2015", "2017", "2019"], "correctAnswer": 2, "subject": "Indian Psychology & Law", "subtopic": "", "explanation": "The Mental Healthcare Act was passed by Indian Parliament in 2017, emphasizing rights of persons with mental illness, access to mental healthcare, and decriminalizing suicide attempts (Section 115). The Act came into force in 2018, representing a shift from punitive to rights-based approach to mental health.", "difficulty": "Easy"}, {"id": 52, "question": "Which legislation in India primarily regulates the control, possession, and trafficking of narcotic drugs and psychotropic substances?", "options": ["Mental Healthcare Act, 2017", "Narcotic Drugs and Psychotropic Substances Act", "Drugs and Cosmetics Act", "Prevention of Illicit Traffic Act"], "correctAnswer": 1, "subject": "Indian Psychology & Law", "subtopic": "", "explanation": "The Narcotic Drugs and Psychotropic Substances (NDPS) Act, 1985 is India's primary legislation regulating control, possession, manufacture, and trafficking of narcotic drugs and psychotropic substances. It provides strict penalties for violations and established enforcement mechanisms for drug control.", "difficulty": "Medium"}, {"id": 53, "question": "The Mental Healthcare Act that emphasizes the rights of persons with mental illness and decriminalizes suicide attempts was passed in:", "options": ["2013", "2015", "2017", "2019"], "correctAnswer": 2, "subject": "Indian Psychology & Law", "subtopic": "", "explanation": "(Duplicate of Q51) The Mental Healthcare Act was passed by Indian Parliament in 2017, emphasizing rights of persons with mental illness, access to mental healthcare, and decriminalizing suicide attempts (Section 115). The Act came into force in 2018, representing a shift from punitive to rights-based approach to mental health.", "difficulty": "Easy"}, {"id": 54, "question": "Match List I with List II:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Max Wertheimer</td><td>a. Collective unconscious</td></tr><tr><td>2. Wolfgang Köhler</td><td>b. Phi phenomenon</td></tr><tr><td>3. Sigmund Freud</td><td>c. Insight learning</td></tr><tr><td>4. Carl Jung</td><td>d. Structural model of personality</td></tr></tbody></table></div>", "options": ["1-b, 2-c, 3-d, 4-a", "1-c, 2-b, 3-a, 4-d", "1-b, 2-d, 3-c, 4-a", "1-a, 2-c, 3-d, 4-b"], "correctAnswer": 0, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Max Wertheimer discovered the phi phenomenon (apparent motion); Wolfgang Köhler demonstrated insight learning in chimpanzees; Sigmund Freud proposed the structural model of personality (id, ego, superego); Carl Jung introduced the concept of collective unconscious. These matchings reflect each theorist's major contributions to psychology.", "difficulty": "Hard"}, {"id": 55, "question": "A chimpanzee repeatedly attempts to reach bananas, becomes frustrated, and then suddenly stacks boxes and climbs on them to obtain the food. There is no gradual strengthening of individual successful responses. Which concept best explains the chimpanzee&#x27;s behavior?", "options": ["Trial-and-error learning", "Insight learning", "Classical conditioning", "Law of Exercise"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Wolfgang Köhler's chimpanzee experiments demonstrated insight learning—sudden problem-solving without gradual trial-and-error. The chimpanzee's sudden realization to stack boxes and climb to reach bananas, without progressive strengthening of responses, exemplifies insight: immediate understanding of relationships leading to solution.", "difficulty": "Medium"}, {"id": 56, "question": "The philosophical movement that provided an important backdrop for humanistic psychology in post-war Europe was:", "options": ["Structuralism", "Existentialism", "Associationism", "Behaviorism"], "correctAnswer": 1, "subject": "Humanistic Psychology", "subtopic": "", "explanation": "Existentialism, emphasizing individual freedom, choice, responsibility, and meaning-making, provided an important philosophical backdrop for humanistic psychology's development in post-war Europe. Humanistic psychologists like Maslow and Rogers shared existentialism's focus on human potential, authenticity, and self-determination.", "difficulty": "Medium"}, {"id": 57, "question": "consider the following cases: Case 1: A child becomes fearful of a clinic after repeated painful injections there. Case 2: A student studies more often because good grades follow studying. Case 3: A cat learns to escape an enclosure after repeatedly discovering the successful response. Which sequence best identifies the underlying learning principles?", "options": ["Operant conditioning → classical conditioning → Law of Effect", "Classical conditioning → operant conditioning → Law of Effect", "Law of Effect → classical conditioning → operant conditioning", "Classical conditioning → Law of Exercise → psychoanalysis"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Case 1 shows classical conditioning (neutral clinic stimulus paired with painful injections becomes fear-eliciting). Case 2 shows operant conditioning (studying increases due to rewarding consequences—good grades). Case 3 illustrates Thorndike's Law of Effect (cat learns successful escape response through satisfying consequences).", "difficulty": "Hard"}, {"id": 58, "question": "Assertion: Gestalt psychology rejected the idea that complex psychological phenomena can be fully understood by simply breaking them into isolated parts. Reason: Gestalt theorists emphasized that the relationships among parts contribute to properties of the whole.", "options": ["Both Assertion and Reason are true, and Reason correctly explains Assertion.", "Both Assertion and Reason are true, but Reason does not correctly explain Assertion.", "Assertion is true, but Reason is false.", "Assertion is false, but Reason is true."], "correctAnswer": 0, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Gestalt psychology rejected structuralism's reductionist approach of breaking consciousness into isolated elements. Gestalt theorists emphasized that psychological phenomena must be understood as organized wholes, where relationships among parts create emergent properties not present in individual elements (\"the whole is greater than sum of parts\").", "difficulty": "Hard"}, {"id": 59, "question": "Match the adult attachment classification described by Mary Main with its corresponding infant classification.<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Dismissing adult</td><td>a. Secure infant</td></tr><tr><td>2. Enmeshed/Preoccupied adult</td><td>b. Resistant infant</td></tr><tr><td>3. Secure adult</td><td>c. Avoidant infant</td></tr></tbody></table></div>", "options": ["1-a, 2-b, 3-c", "1-b, 2-c, 3-a", "1-c, 2-b, 3-a", "1-c, 2-a, 3-b"], "correctAnswer": 2, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Mary Main's Adult Attachment Interview classifications correspond to infant attachment styles: Dismissing adults (deactivating attachment strategies) correspond to avoidant infants; Enmeshed/Preoccupied adults (hyperactivating strategies) correspond to resistant infants; Secure adults correspond to secure infants, showing continuity across lifespan.", "difficulty": "Hard"}, {"id": 60, "question": "A child has developed expectations that the caregiver will be available and responsive because of repeated attachment experiences. The child uses these expectations to guide subsequent attachment behavior. Bowlby referred to this mental representation as:", "options": ["Peak experience", "Internal working model", "Self-actualizing tendency", "Unconditional positive regard"], "correctAnswer": 1, "subject": "Developmental Psychology", "subtopic": "", "explanation": "Bowlby proposed that repeated attachment experiences form internal working models—mental representations of caregiver availability and responsiveness that guide expectations and attachment behaviors. These cognitive-affective schemas influence relationship patterns throughout life and are central to attachment theory.", "difficulty": "Medium"}, {"id": 61, "question": "Carl Rogers originally referred to his therapeutic approach as:", "options": ["Existential psychotherapy", "Client-centered psychotherapy", "Self-actualization therapy", "Gestalt psychotherapy"], "correctAnswer": 1, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Carl Rogers originally termed his therapeutic approach \"client-centered psychotherapy\" (later \"person-centered\"), emphasizing the therapist's provision of unconditional positive regard, empathy, and genuineness to facilitate client self-actualization and growth. This contrasted with directive, expert-oriented therapies.", "difficulty": "Medium"}, {"id": 62, "question": "Which scenario best exemplifies B-love?", "options": ["“I need you because you make me feel complete.”", "“I value you because you satisfy my emotional needs.”", "“I love you because you meet my expectations.”", "“I value you for who you are, independent of what you provide for me”."], "correctAnswer": 3, "subject": "Humanistic Psychology", "subtopic": "", "explanation": "Maslow distinguished D-love (deficiency love—needing someone to fill emotional needs) from B-love (being love—valuing someone for their inherent being, independent of what they provide). B-love is unselfish, appreciative, and non-possessive, characteristic of self-actualized individuals.", "difficulty": "Medium"}, {"id": 63, "question": "Which researcher is associated with the opponent process theory of color vision?", "options": ["Hering", "Helmholtz", "Gibson", "Stevens"], "correctAnswer": 0, "subject": "Biological Psychology", "subtopic": "", "explanation": "Ewald Hering proposed the opponent-process theory of color vision, suggesting color perception involves three opponent pairs: red-green, blue-yellow, and black-white. This explained color afterimages and color blindness patterns better than Helmholtz's trichromatic theory alone. Modern research shows both theories are correct at different processing levels.", "difficulty": "Easy"}, {"id": 64, "question": "Match Column I with Column II.<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Column I</th><th>Column II</th></tr></thead><tbody><tr><td>1. Thorndike</td><td>a. Natural-environment study of animal behavior</td></tr><tr><td>2. Watson</td><td>b. Law of Effect</td></tr><tr><td>3. Hull</td><td>c. Little Albert</td></tr><tr><td>4. Lorenz</td><td>d. Drive-reduction theory</td></tr></tbody></table></div>", "options": ["1-b, 2-c, 3-d, 4-a", "1-c, 2-b, 3-a, 4-d", "1-d, 2-a, 3-b, 4-c", "1-a, 2-d, 3-c, 4-b"], "correctAnswer": 0, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Edward Thorndike formulated the Law of Effect; John Watson conducted the Little Albert classical conditioning experiment demonstrating learned fear; Clark Hull developed drive-reduction theory of motivation; Konrad Lorenz conducted natural-environment studies of animal behavior (ethology), especially imprinting in geese.", "difficulty": "Hard"}, {"id": 65, "question": "A worker receives reinforcement after completing exactly every tenth task. Which schedule is illustrated?", "options": ["Variable ratio", "Fixed ratio", "Fixed interval", "Variable interval"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "A fixed ratio (FR) schedule delivers reinforcement after a set number of responses. Completing exactly every tenth task before receiving reinforcement exemplifies FR-10. Fixed ratio schedules produce high, steady response rates with brief post-reinforcement pauses. Variable schedules involve unpredictable numbers or intervals.", "difficulty": "Medium"}, {"id": 66, "question": "A client with a cat phobia is repeatedly exposed to cats without experiencing the event that originally produced the fear. The procedure described is:", "options": ["Flooding", "Implosion", "Token economy", "Behavioral contracting"], "correctAnswer": 0, "subject": "Clinical & Abnormal Psychology", "subtopic": "", "explanation": "Flooding involves prolonged, intense exposure to the feared stimulus (cats) without the originally feared outcome occurring, leading to extinction of the fear response. Unlike systematic desensitization (gradual exposure with relaxation), flooding is rapid and intense. Implosion uses imagined exposure; token economy uses reinforcement.", "difficulty": "Medium"}, {"id": 67, "question": "Fixed-action patterns are best characterized as:", "options": ["Behaviors acquired exclusively through operant conditioning", "Stereotyped behavior sequences that do not have to be learned", "Flexible behaviors modified through observational learning", "Behaviors that occur only after social reinforcement"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Fixed-action patterns are innate, stereotyped behavioral sequences triggered by specific stimuli (sign stimuli) that occur without learning. Examples include egg-retrieval in geese, web-spinning in spiders. These differ from learned behaviors acquired through conditioning or observation.", "difficulty": "Medium"}, {"id": 68, "question": "A student hears a new telephone number, keeps it active briefly, and later produces it when asked. Which memory process is most directly involved when the student produces the number?", "options": ["Encoding", "Storage", "Retrieval", "Consolidation"], "correctAnswer": 2, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "When the student produces the telephone number when asked, this demonstrates retrieval—accessing and bringing stored information into conscious awareness for use. Encoding involves initially processing information; storage involves maintaining it over time; consolidation stabilizes memories neurologically.", "difficulty": "Medium"}, {"id": 69, "question": "A morpheme is best understood as:", "options": ["The smallest meaningful unit of language", "The smallest unit of sound", "The grammatical arrangement of words", "The overall meaning of a sentence"], "correctAnswer": 0, "subject": "Language & Thought", "subtopic": "", "explanation": "A morpheme is the smallest linguistic unit carrying meaning (e.g., \"un-\" meaning not, \"happy\" meaning joyful, \"-ness\" meaning state of). Morphemes combine to form words. Phonemes are smallest sound units; syntax is grammatical arrangement; semantics is overall meaning.", "difficulty": "Medium"}, {"id": 70, "question": "A student claims: “Once extinction has occurred, the conditioned stimulus can never again produce the conditioned response.” Which finding from conditioning most directly contradicts this statement?", "options": ["Forward conditioning", "Acquisition", "Spontaneous recovery", "Sensory preconditioning"], "correctAnswer": 2, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Spontaneous recovery—the reappearance of an extinguished conditioned response after a rest period without further conditioning—directly contradicts the claim that extinction permanently eliminates the CR. This shows extinction suppresses rather than erases the learned association, which can reemerge.", "difficulty": "Medium"}, {"id": 71, "question": "Spearman&#x27;s g factor is best described as:", "options": ["A specific ability required for one particular task", "A general factor underlying individual differences in intelligence", "A measure of creativity alone", "A culturally specific form of practical intelligence"], "correctAnswer": 1, "subject": "Intelligence", "subtopic": "", "explanation": "Spearman's g factor (general intelligence) is a broad mental capacity influencing performance across diverse cognitive tasks. Using factor analysis, Spearman found positive correlations among different ability tests, proposing g as the common underlying factor plus specific abilities (s) for particular tasks.", "difficulty": "Easy"}, {"id": 72, "question": "Which pairing is CORRECT?", "options": ["Procedural memory — consciously recalled factual information", "Semantic memory — skills and procedures", "Declarative memory — information that can be consciously recalled", "Sensory memory — long-term factual knowledge"], "correctAnswer": 2, "subject": "Language & Thought", "subtopic": "", "explanation": "Declarative (explicit) memory involves information that can be consciously recalled and declared (facts, events). Procedural memory involves skills/procedures; semantic memory involves factual knowledge; sensory memory is brief initial registration. Option C correctly matches the memory type with its definition.", "difficulty": "Medium"}, {"id": 73, "question": "The gate theory of pain was proposed by:", "options": ["Wever and Bray", "Melzack and Wall", "Yerkes and Dodson", "Hubel and Wiesel"], "correctAnswer": 1, "subject": "Biological Psychology", "subtopic": "", "explanation": "Ronald Melzack and Patrick Wall proposed the gate control theory of pain in 1965, suggesting spinal cord mechanisms can modulate pain signals before reaching the brain. Psychological factors can \"open\" or \"close\" the gate, explaining why pain perception varies with attention, emotion, and context.", "difficulty": "Easy"}, {"id": 74, "question": "Thurstone&#x27;s factors were described as:", "options": ["More specific than g but more general than s", "More general than g but more specific than s", "Completely unrelated to general intelligence", "Identical to Gardner's multiple intelligences"], "correctAnswer": 0, "subject": "Intelligence", "subtopic": "", "explanation": "L.L. Thurstone identified seven primary mental abilities (verbal comprehension, word fluency, number, space, associative memory, perceptual speed, reasoning) that are more specific than Spearman's general factor (g) but more general than task-specific factors (s), representing intermediate-level abilities.", "difficulty": "Medium"}, {"id": 75, "question": "The principle underlying systematic desensitization is that:", "options": ["Anxiety and deep relaxation cannot be experienced simultaneously", "Punishment is always more effective than reinforcement", "Avoidance strengthens extinction", "Fear increases whenever relaxation is introduced"], "correctAnswer": 0, "subject": "Clinical & Abnormal Psychology", "subtopic": "", "explanation": "Systematic desensitization, developed by Joseph Wolpe, is based on reciprocal inhibition—the principle that anxiety and deep relaxation are incompatible states that cannot coexist. By pairing relaxation with gradually intensifying anxiety-provoking stimuli, the relaxation response inhibits and replaces the anxiety response.", "difficulty": "Medium"}, {"id": 76, "question": "A patient engages in an undesirable behavior primarily because it produces attention from staff. The therapist temporarily removes the patient from the reinforcing environment immediately after the behavior. This most closely illustrates:", "options": ["Time-out", "Systematic desensitization", "Conditioned aversion", "Shaping"], "correctAnswer": 0, "subject": "Clinical & Abnormal Psychology", "subtopic": "", "explanation": "Time-out involves temporarily removing a person from a reinforcing environment immediately after undesirable behavior, thereby reducing access to positive reinforcement (like staff attention) that maintained the behavior. This differs from systematic desensitization (anxiety treatment), aversion therapy, or shaping (reinforcing successive approximations).", "difficulty": "Medium"}, {"id": 77, "question": "Paivio&#x27;s dual-code hypothesis proposes that information can be represented through:", "options": ["Sensory and short-term systems", "Verbal and nonverbal/imagery-based codes", "Procedural and declarative systems only", "Encoding and retrieval codes only"], "correctAnswer": 1, "subject": "Language & Thought", "subtopic": "", "explanation": "Allan Paivio's dual-code hypothesis proposes that information can be represented through two distinct coding systems: verbal (linguistic, symbolic) and nonverbal/imagery-based (visual, concrete). This explains why concrete words (easily imaged) are remembered better than abstract words.", "difficulty": "Medium"}, {"id": 78, "question": "Which theorist proposed the triarchic theory of intelligence?", "options": ["Robert Sternberg", "Raymond Cattell", "Charles Spearman", "Howard Gardner"], "correctAnswer": 0, "subject": "Intelligence", "subtopic": "", "explanation": "Robert Sternberg proposed the triarchic theory of intelligence comprising three aspects: analytical (problem-solving), creative (dealing with novelty), and practical (adapting to real-world demands). This contrasts with Gardner's multiple intelligences, Cattell's fluid/crystallized theory, and Spearman's g factor.", "difficulty": "Medium"}, {"id": 79, "question": "Match the classical conditioning concept with its defining feature.<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Column I</th><th>Column II</th></tr></thead><tbody><tr><td>1. Acquisition</td><td>a. CR after rest following extinction</td></tr><tr><td>2. Extinction</td><td>b. Learning the stimulus association</td></tr><tr><td>3. Spontaneous recovery</td><td>c. Similar stimuli produce CR</td></tr><tr><td>4. Generalization</td><td>d. CS presented without UCS</td></tr></tbody></table></div>", "options": ["1-b, 2-d, 3-a, 4-c", "1-d, 2-b, 3-c, 4-a", "1-a, 2-c, 3-d, 4-b", "1-c, 2-a, 3-b, 4-d"], "correctAnswer": 0, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Acquisition is learning the CS-UCS association; Extinction occurs when CS is presented repeatedly without UCS, weakening the CR; Spontaneous recovery is reappearance of CR after rest following extinction; Generalization occurs when similar stimuli to the CS also produce the CR. These are fundamental classical conditioning phenomena.", "difficulty": "Hard"}, {"id": 80, "question": "A researcher presents participants with weak signals embedded in noise and asks them to indicate whether a signal is present. The researcher analyzes performance using ROC curves. Which conceptual area is being investigated?", "options": ["Signal detection theory", "Place-resonance theory", "Opponent process theory", "Gate theory"], "correctAnswer": 0, "subject": "Biological Psychology", "subtopic": "", "explanation": "Signal detection theory analyzes performance in detecting weak signals embedded in noise using measures like hits, misses, false alarms, and correct rejections, often visualized with ROC (receiver operating characteristic) curves. This framework separates sensory sensitivity from response bias in perceptual decision-making.", "difficulty": "Medium"}, {"id": 81, "question": "Which of the following is the most important distinction between reinforcement and punishment?", "options": ["Reinforcement always involves rewards, whereas punishment always involves pain", "Reinforcement increases behavior, whereas punishment decreases behavior", "Reinforcement occurs in animals, whereas punishment occurs in humans", "Reinforcement is classical, whereas punishment is operant"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "The fundamental distinction is functional: reinforcement (positive or negative) always increases the future frequency of a behavior, while punishment (positive or negative) always decreases it. This definitional difference is more important than whether rewards or aversive stimuli are involved.", "difficulty": "Medium"}, {"id": 82, "question": "Which sequence most appropriately corresponds to the concepts in the supplied material?", "options": ["Phoneme → morpheme → syntax → semantics → pragmatics", "Morpheme → phoneme → semantics → syntax → pragmatics", "Phoneme → syntax → morpheme → pragmatics → semantics", "Syntax → phoneme → morpheme → semantics → pragmatics"], "correctAnswer": 0, "subject": "Language & Thought", "subtopic": "", "explanation": "This sequence represents language organization from smallest to largest units: phonemes (sounds) combine into morphemes (meaningful units), which arrange via syntax (grammar) to create semantics (meaning), used within pragmatics (social context). This reflects the hierarchical structure of language.", "difficulty": "Hard"}, {"id": 83, "question": "The error in the K-word problem is most directly explained by:", "options": ["Representativeness heuristic", "Availability heuristic", "Base-rate information being deliberately ignored because of numerical calculation", "Insight learning"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "The K-word problem error (overestimating words starting with K vs. having K as third letter) is explained by the availability heuristic—judging frequency/probability based on how easily examples come to mind. Words starting with K are more cognitively available, leading to overestimation despite more words having K in third position.", "difficulty": "Medium"}, {"id": 84, "question": "Researchers find that differences in the linguistic categories available to speakers are associated with differences in how those speakers conceptualize certain aspects of experience. This finding would be most relevant to:", "options": ["Whorfian hypothesis", "Law of Effect", "Levels-of-processing theory", "Drive-reduction theory"], "correctAnswer": 0, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "The Whorfian hypothesis (linguistic relativity) proposes that language influences thought and perception—differences in linguistic categories available to speakers are associated with differences in how they conceptualize experience. This suggests language shapes cognition, though the strong deterministic version is largely discredited. simplypsychology+3", "difficulty": "Easy"}, {"id": 85, "question": "Gardner&#x27;s seven intelligences include:", "options": ["Linguistic, logical-mathematical, spatial, musical, bodily-kinesthetic, interpersonal, and intrapersonal", "Verbal, numerical, perceptual, fluid, crystallized, contextual, and experiential", "Componential, experiential, contextual, linguistic, spatial, numerical, and perceptual", "General, specific, fluid, crystallized, musical, contextual, and interpersonal"], "correctAnswer": 0, "subject": "Intelligence", "subtopic": "", "explanation": "Howard Gardner's theory of multiple intelligences originally identified seven distinct intelligences: linguistic, logical-mathematical, spatial, musical, bodily-kinesthetic, interpersonal (understanding others), and intrapersonal (understanding self). Later he added naturalistic and considered existential intelligence. psychology+3", "difficulty": "Medium"}, {"id": 86, "question": "Assertion: Deep processing can lead to better memory than shallow processing. Reason: Levels-of-processing theory proposes that the way information is processed influences later memory.", "options": ["Both Assertion and Reason are true, and Reason correctly explains Assertion.", "Both Assertion and Reason are true, but Reason does not correctly explain Assertion.", "Assertion is true, but Reason is false.", "Assertion is false, but Reason is true."], "correctAnswer": 0, "subject": "Language & Thought", "subtopic": "", "explanation": "Levels-of-processing theory (Craik & Lockhart) proposes that deeper, more meaningful processing (semantic, elaborative) leads to better memory than shallow processing (structural, phonemic). The reason correctly explains why deep processing produces superior retention—encoding quality determines later retrievability. completeera+3", "difficulty": "Hard"}, {"id": 87, "question": "A participant is asked to recall the words: ROSE, DOG, TULIP, CAT, LILY, HORSE. The participant recalls ROSE, TULIP, LILY together and then DOG, CAT, HORSE together. This pattern is an example of:", "options": ["Primacy", "Clustering", "Recognition", "Generation"], "correctAnswer": 1, "subject": "Language & Thought", "subtopic": "", "explanation": "When a participant recalls words grouped by category (flowers together, animals together) despite random presentation, this demonstrates clustering—organizing information during recall based on semantic categories. This shows how memory is reconstructive and influenced by organizational strategies, not just passive storage. resolve.cambridge+3", "difficulty": "Medium"}, {"id": 88, "question": "Fluid intelligence refers primarily to the ability to:", "options": ["Use knowledge acquired through schooling", "Quickly grasp relationships in novel situations and make correct deductions", "Apply learned vocabulary to familiar problems", "Demonstrate musical or interpersonal skills"], "correctAnswer": 1, "subject": "Intelligence", "subtopic": "", "explanation": "Fluid intelligence involves reasoning, problem-solving, and adapting to novel situations independent of acquired knowledge. It includes abilities like identifying patterns, solving new problems, and making deductions. This contrasts with crystallized intelligence, which involves using learned knowledge and experience. resolve.cambridge+3", "difficulty": "Medium"}, {"id": 89, "question": "A person decides which restaurant to visit because several memorable experiences of that restaurant immediately come to mind. This decision most clearly illustrates:", "options": ["Representativeness heuristic", "Availability heuristic", "Base-rate reasoning", "Functional fixedness"], "correctAnswer": 1, "subject": "Language & Thought", "subtopic": "", "explanation": "Choosing a restaurant because memorable experiences immediately come to mind exemplifies the availability heuristic—judging likelihood or value based on how easily examples are retrieved from memory. Vivid, recent, or emotionally salient memories are more available and disproportionately influence decisions. resolve.cambridge+3", "difficulty": "Medium"}, {"id": 90, "question": "A child is placed on an apparatus consisting of a transparent surface with an apparent drop beneath part of it. The procedure is designed to determine whether the child perceives a difference in depth. This apparatus is associated with:", "options": ["Gibson and Walk", "Gibson", "Yerkes and Dodson", "Hubel and Wiesel"], "correctAnswer": 0, "subject": "Biological Psychology", "subtopic": "", "explanation": "The visual cliff apparatus, developed by Eleanor Gibson and Richard Walk, consists of a transparent surface with an apparent drop beneath part, used to test depth perception in infants and animals. Their research showed that depth perception emerges early and may be partly innate, not solely learned.", "difficulty": "Medium"}, {"id": 91, "question": "Operant conditioning is primarily based on learning the relationship between:", "options": ["Stimulus intensity and sensation", "Behavior and its consequences", "Unconscious wishes and symptoms", "Biological drives and instincts"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Operant conditioning, developed by B.F. Skinner building on Thorndike's Law of Effect, is based on learning associations between behaviors and their consequences (reinforcement or punishment). Behaviors followed by satisfying consequences increase; those followed by unpleasant consequences decrease.", "difficulty": "Medium"}, {"id": 92, "question": "Two participants studied the same word list. Participant X is asked to write down as many studied words as possible. Participant Y is shown words one at a time and asked whether each word appeared in the original list. Which statement best characterizes the two tasks?", "options": ["X = recognition; Y = recall", "X = clustering; Y = primacy", "X = recall; Y = recognition", "X = generation-recognition; Y = clustering"], "correctAnswer": 2, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Participant X writing down studied words demonstrates recall—retrieving information without external cues. Participant Y identifying whether shown words appeared on the list demonstrates recognition—identifying previously encountered information when presented. Recognition is typically easier than recall.", "difficulty": "Medium"}, {"id": 93, "question": "Thorndike&#x27;s Law of Effect subsequently formed the basis for:", "options": ["Classical conditioning", "Operant conditioning", "Sensory preconditioning", "Drive-reduction theory"], "correctAnswer": 1, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "Thorndike's Law of Effect (behaviors followed by satisfying consequences are strengthened) directly formed the basis for Skinner's operant conditioning theory. Skinner extended this principle, systematically studying how reinforcement and punishment shape voluntary behavior through consequences.", "difficulty": "Medium"}, {"id": 94, "question": "In Pavlovian classical conditioning, the food powder presented to dogs before conditioning is the:", "options": ["Conditioned stimulus", "Conditioned response", "Unconditioned stimulus", "Unconditioned response"], "correctAnswer": 2, "subject": "Learning & Conditioning", "subtopic": "", "explanation": "In Pavlov's classical conditioning, food powder presented before conditioning is the unconditioned stimulus (UCS) because it naturally and automatically elicits salivation (unconditioned response) without prior learning. The bell becomes the conditioned stimulus after pairing with food.", "difficulty": "Medium"}, {"id": 95, "question": "Which sequence best represents the historical transition described in the source?", "options": ["Structuralism → functionalism, behaviorism, and Gestalt psychology", "Behaviorism → structuralism → psychoanalysis", "Psychoanalysis → structuralism → functionalism", "Humanism → behaviorism → structuralism"], "correctAnswer": 0, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "This sequence represents the historical transition in early psychology: Wundt and Titchener's structuralism (analyzing consciousness into elements) gave way to functionalism (James—mental processes' functions), behaviorism (Watson, Skinner—observable behavior), and Gestalt psychology (Wertheimer—organized wholes).", "difficulty": "Hard"}, {"id": 96, "question": "A researcher asks participants to describe their immediate conscious experiences while viewing a stimulus. Which historical approach does this most closely resemble?", "options": ["Behaviorism", "Psychoanalysis", "Structuralism", "Functionalism"], "correctAnswer": 2, "subject": "History & Schools of Psychology", "subtopic": "", "explanation": "Asking participants to describe immediate conscious experiences while viewing stimuli exemplifies structuralism's introspective method. Structuralists trained observers to report basic elements of consciousness (sensations, feelings, images) in response to standardized stimuli, aiming to analyze mental structure.", "difficulty": "Medium"}, {"id": 97, "question": "A student has learned a person&#x27;s name but, when asked to produce it, cannot retrieve it despite feeling that the name is almost accessible. This most directly illustrates:", "options": ["Encoding failure", "Storage failure", "Retrieval difficulty", "Semantic encoding"], "correctAnswer": 2, "subject": "Language & Thought", "subtopic": "", "explanation": "When a student cannot produce a learned name despite feeling it's accessible (tip-of-the-tongue phenomenon), this illustrates retrieval difficulty—temporary inability to access stored information despite successful encoding and storage. The information exists in memory but cannot be retrieved at that moment.", "difficulty": "Medium"}, {"id": 98, "question": "Which finding represents the primacy effect?", "options": ["Superior memory for the final items in a list", "Superior memory for the initial items in a list", "Superior memory for emotionally arousing items", "Superior recognition compared with recall"], "correctAnswer": 1, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "The primacy effect refers to better memory for items at the beginning of a list, attributed to greater rehearsal and transfer to long-term memory. The recency effect shows better memory for final items (still in short-term memory). Both contribute to the serial position curve in free recall.", "difficulty": "Medium"}, {"id": 99, "question": "George Miller&#x27;s work is associated with the idea that short-term memory can hold approximately:", "options": ["2 ± 1 chunks", "5 ± 1 chunks", "7 ± 2 chunks", "12 ± 4 chunks"], "correctAnswer": 2, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "George Miller's classic 1956 paper \"The Magical Number Seven, Plus or Minus Two\" proposed that short-term memory capacity is approximately 7 ± 2 chunks (meaningful units). This finding became foundational in cognitive psychology, though later research suggests capacity may be closer to 4 ± 1 chunks for some materials.", "difficulty": "Easy"}, {"id": 100, "question": "Which technique is most directly intended to facilitate transfer of information into long-term memory?<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Q#</th><th>Correct Answer</th><th>Explanation</th></tr></thead><tbody><tr><td>1</td><td>B) Receptive–productive language lag</td><td>This phenomenon describes when infants and toddlers comprehend significantly more language than they can verbally express. Research shows babies can understand complex instructions and recognize many object names by six months, yet may only produce one or two words in response. This gap between receptive (understanding) and productive/expressive (speaking) language is normal in early development.</td></tr><tr><td>2</td><td>C) Sociocultural theory</td><td>Lev Vygotsky&#x27;s sociocultural theory emphasizes that cognitive development occurs through social interaction, guided participation with more knowledgeable others, and the use of cultural tools like language. Children learn by engaging in collaborative activities within their cultural context, rather than through individual discovery alone. This contrasts with Piaget&#x27;s constructivism which focuses more on individual exploration.</td></tr><tr><td>3</td><td>B) Differentiation from primary caregiver</td><td>Margaret Mahler&#x27;s separation-individuation theory describes how infants develop a sense of individual identity separate from their primary caregiver (typically the mother) between 5-24 months. The process includes sub-stages like differentiation/hatching where the baby begins recognizing the caregiver as a separate person. This is not about superego formation or moral development. openlab.</td></tr><tr><td>4</td><td>B) Concrete operational stage</td><td>Children in Piaget&#x27;s concrete operational stage (ages 7-11) can understand conservation of volume, mass, and number, but struggle with abstract hypothetical reasoning. They think logically about concrete, tangible events and situations they can observe directly. Hypothetical-deductive reasoning develops later in the formal operational stage during adolescence.</td></tr><tr><td>5</td><td>C) Easy</td><td>Thomas and Chess identified three temperament types. Easy children (about 40% of sample) show regular biological rhythms, positive mood, adaptability to new situations, and moderate emotional reactions. Difficult children have irregular habits and negative reactions; slow-to-warm children are less active and need time to adapt to novelty.</td></tr><tr><td>6</td><td>A) Empathy</td><td>Empathy is the ability to understand and share another person&#x27;s emotional state from their perspective, involving both cognitive understanding and emotional resonance. Projection, sublimation, and displacement are defense mechanisms that involve attributing one&#x27;s own feelings to others or redirecting impulses, not understanding others&#x27; emotions.</td></tr><tr><td>7</td><td>B) Identity diffusion</td><td>Erik Erikson&#x27;s fifth psychosocial stage (Identity vs. Role Confusion) occurs during adolescence. Failure to resolve this crisis results in identity diffusion—a lack of clear direction, commitment, or coherent sense of self. Adolescents in diffusion have neither explored identity options nor committed to values, beliefs, or life directions.</td></tr><tr><td>8</td><td>C) Using a pencil to draw shapes</td><td>Fine motor coordination involves small muscle movements of hands, fingers, and wrists for precise tasks like drawing, writing, cutting, and manipulating small objects. Climbing stairs, throwing balls, and balancing involve gross motor skills using large muscle groups of arms, legs, and trunk for whole-body movements.</td></tr><tr><td>9</td><td>B) Social competence</td><td>Consistent avoidance of peer interaction directly indicates problems with social competence—the ability to interact effectively with others, form relationships, and navigate social situations. While other domains may contribute, social competence is most directly implicated. Motor maturation, language, and executive functioning affect different behavioral domains.</td></tr><tr><td>10</td><td>C) Attachment theory</td><td>John Bowlby&#x27;s attachment theory proposes that early emotional bonds with caregivers form internal working models that influence later emotional regulation, relationship patterns, and psychological development throughout life. Secure attachment in childhood predicts better social competence and wellbeing across the lifespan. simplypsychology+3</td></tr><tr><td>11</td><td>C) Concrete operational stage</td><td>Piaget&#x27;s concrete operational stage (ages 7-11) is characterized by the ability to think logically about concrete events, understand conservation, reversibility, classification, and seriation. Children can perform mental operations on tangible objects but not yet on abstract hypothetical situations, which requires formal operational thinking. simplypsychology+3</td></tr><tr><td>12</td><td>C) Object-relations theory</td><td>Object-relations theory, a psychodynamic approach, proposes that people respond to the world based on internalized representations (objects) of important early relationships. These mental representations of caregivers and relationship patterns learned in childhood shape how individuals perceive and interact with others throughout life. openlab.bmcc.cuny+3</td></tr><tr><td>13</td><td>C) Toddlerhood language acceleration</td><td>The vocabulary spurt (naming explosion) occurs typically between 18-24 months during toddlerhood, when children shift from learning 1-2 words per week to acquiring 5-10+ new words daily. This rapid word learning coincides with developments in symbolic thinking and marks a dramatic acceleration in language acquisition. bbc+4</td></tr><tr><td>14</td><td>A) Preconventional morality</td><td>Kohlberg&#x27;s preconventional level (typically until age 8-9) includes Stage 1 (obedience/punishment orientation) and Stage 2 (instrumental purpose/reward orientation). Children at this level make moral decisions based on avoiding punishment and obtaining rewards rather than internalized moral principles or social conventions. simplypsychology+4</td></tr><tr><td>15</td><td>A) Egocentrism in adolescence</td><td>David Elkind identified the imaginary audience (belief that others constantly watch and judge) and personal fable (belief in personal uniqueness and invincibility) as two components of adolescent egocentrism. These cognitive distortions reflect teenagers&#x27; difficulty distinguishing their own perspective from others&#x27; during this developmental period.</td></tr><tr><td>16</td><td>C) Gap between independent and assisted performance</td><td>Vygotsky&#x27;s Zone of Proximal Development (ZPD) refers to the difference between what a learner can do independently and what they can achieve with guidance from a more knowledgeable other. It represents the potential for learning through scaffolding and guided participation within the sociocultural context.</td></tr><tr><td>17</td><td>C) Resistant/ambivalent</td><td>Resistant (ambivalent) attachment is characterized by intense distress upon caregiver separation and difficulty being comforted when the caregiver returns. Children may show anger or resistance toward the caregiver despite seeking proximity. Secure children are easily comforted; avoidant children show minimal distress; disorganized children show contradictory behaviors.</td></tr><tr><td>18</td><td>B) Recognize false beliefs in others</td><td>Theory of Mind is best demonstrated when children understand that others can hold beliefs different from their own and from reality (false belief understanding). Standard tasks like Sally-Anne test assess this ability, which typically emerges around ages 4-5 years. This shows understanding that mental states guide behavior.</td></tr><tr><td>19</td><td>B) Concrete operational reasoning</td><td>Reversibility—the ability to mentally undo actions or operations—is a key achievement of Piaget&#x27;s concrete operational stage. Children understand that pouring liquid back into the original glass restores the original amount, or that 5+3=8 means 8-3=5. This logical skill doesn&#x27;t emerge in preoperational or sensorimotor stages. simplypsychology+3</td></tr><tr><td>20</td><td>B) Social anxiety disorder</td><td>Social anxiety disorder (social phobia) is characterized by persistent, intense fear of negative evaluation, embarrassment, or humiliation in social situations. Individuals worry excessively about criticism, rejection, or being judged negatively, leading to avoidance of social interactions. This differs from agoraphobia (fear of situations where escape is difficult) and specific phobias. pmc.ncbi.nlm.nih+3</td></tr><tr><td>21</td><td>C) Dr. C. H. Rice</td><td>Dr. C. H. Rice made the first systematic attempt to standardize mental tests in India by adapting Binet&#x27;s intelligence test in Urdu and Punjabi during the 1930s. S. M. Mohsin later developed an intelligence test in Hindi, and Mahalanobis standardized Binet&#x27;s test in Bengali around the same period.</td></tr><tr><td>22</td><td>C) Proximity</td><td>The Gestalt law of proximity states that objects or shapes positioned close to one another are perceived as forming groups or belonging together, regardless of their actual shapes, sizes, or characteristics. This principle explains how we naturally organize visual stimuli into meaningful patterns based on spatial nearness.</td></tr><tr><td>23</td><td>A) Perceptual constancy</td><td>Perceptual constancy is the tendency to perceive objects as maintaining stable properties (size, shape, color, brightness) despite changes in sensory input due to viewing angle, distance, or lighting conditions. This allows us to recognize a white mug as white under both bright and dim illumination, maintaining stable perception.</td></tr><tr><td>24</td><td>D) Occipital lobe</td><td>The occipital lobe, located at the back of the brain, is the primary visual processing center containing the primary visual cortex (V1/Brodmann area 17). It receives and interprets visual signals from the eyes, processing features like edges, orientation, color, motion, and spatial location. Other lobes handle different functions.</td></tr><tr><td>25</td><td>B) Recognize false beliefs in others</td><td>(Duplicate of Q18) Theory of Mind is best demonstrated when children understand that others can hold beliefs different from their own and from reality (false belief understanding). Standard tasks like Sally-Anne test assess this ability, which typically emerges around ages 4-5 years. This shows understanding that mental states guide behavior.</td></tr><tr><td>26</td><td>B) Concrete operational reasoning</td><td>(Duplicate of Q19) Reversibility—the ability to mentally undo actions or operations—is a key achievement of Piaget&#x27;s concrete operational stage. Children understand that pouring liquid back into the original glass restores the original amount, or that 5+3=8 means 8-3=5. This logical skill doesn&#x27;t emerge in preoperational or sensorimotor stages.</td></tr><tr><td>27</td><td>B) Iconic memory</td><td>Iconic memory is visual sensory memory that retains visual information for a very brief period (150-500 milliseconds) after stimulus offset. When Rahul briefly noticed clothes in the corridor and the visual information faded rapidly, this exemplifies iconic memory—the fleeting visual sensory register that provides a momentary snapshot of the visual scene.</td></tr><tr><td>28</td><td>A) Thomas Hobbes</td><td>Thomas Hobbes argued that memories are residual traces (decaying sense) of previous sensory impressions. He proposed that all mental content originates from sensation, and memories are weakened sensory experiences that persist after the original stimulus ends. This empiricist view influenced later associationist theories of memory and learning.</td></tr><tr><td>29</td><td>A) Generalization</td><td>Stimulus generalization occurs when a conditioned response (fear) elicited by one stimulus (the biting dog) spreads to similar stimuli (other dogs). After being bitten by one dog, the child&#x27;s fear response generalizes to the broader category of dogs. This differs from discrimination, where responses remain specific to the original conditioned stimulus.</td></tr><tr><td>30</td><td>B) Thoughts and wishes that can operate outside conscious awareness</td><td>Freud&#x27;s unconscious contains thoughts, wishes, memories, feelings, and instinctual drives that operate outside conscious awareness yet powerfully influence behavior, emotions, and decisions. The unconscious holds repressed or unacceptable content that remains inaccessible to consciousness without therapeutic intervention like free association or dream analysis.</td></tr><tr><td>31</td><td>B) Alcmaeon, Protagoras, Democritus, Hippocrates</td><td>Pre-Socratic philosophers (6th-5th century BCE) preceded or were contemporaries of Socrates. Alcmaeon (medical theorist), Protagoras (sophist), Democritus (atomist), and Hippocrates (physician) all belong to this period. Plato, Aristotle, Augustine, Avicenna, and Freud are from later periods and not pre-Socratic thinkers.</td></tr><tr><td>32</td><td>C) Report their own sensory experiences following physical stimulation</td><td>In Wundt&#x27;s Leipzig laboratory (established 1879), collaborators underwent extensive training in introspection to report their immediate conscious experiences in response to standardized stimuli like lights, sounds, or weights. This highly controlled method aimed to analyze consciousness into basic elements through trained self-observation.</td></tr><tr><td>33</td><td>B) Repression and disguised expression of unconscious impulses</td><td>Freud proposed that unacceptable impulses are prevented from entering consciousness through repression, yet these unconscious contents continue to influence behavior and may emerge indirectly as psychological symptoms, dreams, slips, or neurotic behaviors. The impulse remains unconscious but finds disguised expression through symptoms.</td></tr><tr><td>34</td><td>C) Associative or Pavlovian conditioning</td><td>Classical conditioning, discovered by Ivan Pavlov, is also called associative conditioning or Pavlovian conditioning. It involves learning associations between stimuli, where a neutral stimulus becomes associated with an unconditioned stimulus to elicit a conditioned response. This differs from operant/instrumental conditioning which involves behavior-consequence associations.</td></tr><tr><td>35</td><td>C) Phrenology</td><td>Phrenology, founded by Franz Joseph Gall, claimed that intelligence, personality traits, and mental abilities could be determined by examining the shape, size, and contours of different skull regions. This pseudoscience proposed that brain areas correspond to specific faculties and that skull morphology reflects brain development.</td></tr><tr><td>36</td><td>B) Thinking as evidence of one&#x27;s existence</td><td>Descartes&#x27; &quot;Cogito, ergo sum&quot; (I think, therefore I am) establishes thinking as indubitable proof of existence. Even if all sensory experience is deceptive, the very act of doubting or thinking guarantees the thinker&#x27;s existence as a thinking entity. This became the first principle of his philosophy and foundation for certain knowledge.</td></tr><tr><td>37</td><td>B) Franz Joseph Gall</td><td>Phrenology was founded by German physician Franz Joseph Gall (1758-1828), who proposed that the brain consists of multiple distinct organs corresponding to different mental faculties, and that skull shape reflects the development of these brain areas. Though now discredited, phrenology influenced early localization theories.</td></tr><tr><td>38</td><td>A) Dogs salivating before food was presented</td><td>Pavlov&#x27;s classical conditioning research began with observations that dogs in his digestion studies started salivating before food was actually presented—responding to cues associated with feeding like the experimenter&#x27;s footsteps or laboratory apparatus. This led him to investigate conditioned reflexes systematically.</td></tr><tr><td>39</td><td>B) A behaviour increases because it is followed by a reward</td><td>Positive reinforcement occurs when a behavior increases in frequency because it is followed by the presentation of a rewarding stimulus. The reward strengthens the behavior, making it more likely to occur again. This differs from punishment (which decreases behavior) and negative reinforcement (removal of aversive stimulus).</td></tr><tr><td>40</td><td>A) Darwin&#x27;s theory of natural selection</td><td>Aristotle&#x27;s teleological explanations proposed that human reasoning and behavior serve predetermined purposes or final causes. Darwin&#x27;s theory of natural selection differs fundamentally by explaining traits and behaviors through evolutionary adaptation and survival value without predetermined purpose, emphasizing variation and environmental selection.</td></tr><tr><td>41</td><td>A) Edward Thorndike</td><td>Edward Thorndike formulated the Law of Effect, stating that behaviors followed by satisfying consequences are strengthened (more likely to recur), while behaviors followed by unpleasant consequences are weakened. This principle became foundational for operant conditioning and behaviorist learning theory developed later by Skinner.</td></tr><tr><td>42</td><td>B) Common-sense psychological ideas transmitted through sayings, aphorisms, and proverbs</td><td>Folk psychology refers to everyday, common-sense psychological understanding transmitted culturally through proverbs, sayings, aphorisms, and shared beliefs about human behavior and mental processes. It contrasts with formal scientific psychology and represents intuitive theories people use to explain behavior.</td></tr><tr><td>43</td><td>B) Repression</td><td>Freud proposed that repression is the primary defense mechanism preventing unacceptable wishes, impulses, and memories from entering conscious awareness. These repressed contents remain in the unconscious yet continue to influence behavior, emotions, and may emerge as symptoms, dreams, or Freudian slips.</td></tr><tr><td>44</td><td>B) Spinoza — cognitive appraisal influencing emotional response</td><td>Benedict de Spinoza proposed that emotions are influenced by cognitive appraisal—how we think about situations affects our emotional responses. This anticipates modern cognitive theories of emotion. Descartes proposed mind-body dualism, Hobbes emphasized sensation and reflection, and Locke proposed empiricist ideas about experience.</td></tr><tr><td>45</td><td>B) Assimilation fits new information into an existing schema, whereas accommodation modifies the schema</td><td>Piaget distinguished assimilation (incorporating new experiences into existing cognitive schemas without changing them) from accommodation (modifying existing schemas or creating new ones when new information doesn&#x27;t fit). Both processes work together in cognitive adaptation and development.</td></tr><tr><td>46</td><td>B) Accommodation</td><td>When a child must modify an existing grasping pattern (schema) to successfully manipulate a differently shaped rattle, this illustrates accommodation—adjusting cognitive structures to incorporate new experiences that don&#x27;t fit existing schemas. Assimilation would involve using the existing grasp without modification.</td></tr><tr><td>47</td><td>B) Innate or unlearned</td><td>In classical conditioning, an unconditioned stimulus (UCS) naturally and automatically triggers an unconditioned response (UCR) without prior learning. The response is innate, reflexive, or unlearned (e.g., food causing salivation, loud noise causing startle). This contrasts with conditioned responses which are learned through association.</td></tr><tr><td>48</td><td>B) 1995</td><td>India&#x27;s first comprehensive disability rights legislation, The Persons with Disabilities (Equal Opportunities, Protection of Rights and Full Participation) Act, was enacted in 1995 and came into force on February 7, 1996. This landmark law addressed rights, rehabilitation, and full participation of persons with disabilities.</td></tr><tr><td>49</td><td>B) Establishment of the University of Leipzig laboratory in 1879</td><td>Wilhelm Wundt&#x27;s establishment of the first experimental psychology laboratory at the University of Leipzig in 1879 marked the formal beginning of psychology as an independent scientific discipline separate from philosophy and physiology. This event is widely recognized as the birth of modern scientific psychology.</td></tr><tr><td>50</td><td>A) Encopresis</td><td>Encopresis is the repeated passage of feces into inappropriate places (clothing, floor) by a child developmentally old enough for bowel control (typically age 4+). It may be involuntary or intentional. Enuresis refers to involuntary urination; coprolalia is involuntary utterance of obscenities associated with Tourette&#x27;s.</td></tr><tr><td>51</td><td>C) 2017</td><td>The Mental Healthcare Act was passed by Indian Parliament in 2017, emphasizing rights of persons with mental illness, access to mental healthcare, and decriminalizing suicide attempts (Section 115). The Act came into force in 2018, representing a shift from punitive to rights-based approach to mental health.</td></tr><tr><td>52</td><td>B) Narcotic Drugs and Psychotropic Substances Act</td><td>The Narcotic Drugs and Psychotropic Substances (NDPS) Act, 1985 is India&#x27;s primary legislation regulating control, possession, manufacture, and trafficking of narcotic drugs and psychotropic substances. It provides strict penalties for violations and established enforcement mechanisms for drug control.</td></tr><tr><td>53</td><td>C) 2017</td><td>(Duplicate of Q51) The Mental Healthcare Act was passed by Indian Parliament in 2017, emphasizing rights of persons with mental illness, access to mental healthcare, and decriminalizing suicide attempts (Section 115). The Act came into force in 2018, representing a shift from punitive to rights-based approach to mental health.</td></tr><tr><td>54</td><td>A) 1-b, 2-c, 3-d, 4-a</td><td>Max Wertheimer discovered the phi phenomenon (apparent motion); Wolfgang Köhler demonstrated insight learning in chimpanzees; Sigmund Freud proposed the structural model of personality (id, ego, superego); Carl Jung introduced the concept of collective unconscious. These matchings reflect each theorist&#x27;s major contributions to psychology.</td></tr><tr><td>55</td><td>B) Insight learning</td><td>Wolfgang Köhler&#x27;s chimpanzee experiments demonstrated insight learning—sudden problem-solving without gradual trial-and-error. The chimpanzee&#x27;s sudden realization to stack boxes and climb to reach bananas, without progressive strengthening of responses, exemplifies insight: immediate understanding of relationships leading to solution.</td></tr><tr><td>56</td><td>B) Existentialism</td><td>Existentialism, emphasizing individual freedom, choice, responsibility, and meaning-making, provided an important philosophical backdrop for humanistic psychology&#x27;s development in post-war Europe. Humanistic psychologists like Maslow and Rogers shared existentialism&#x27;s focus on human potential, authenticity, and self-determination.</td></tr><tr><td>57</td><td>B) Classical conditioning → operant conditioning → Law of Effect</td><td>Case 1 shows classical conditioning (neutral clinic stimulus paired with painful injections becomes fear-eliciting). Case 2 shows operant conditioning (studying increases due to rewarding consequences—good grades). Case 3 illustrates Thorndike&#x27;s Law of Effect (cat learns successful escape response through satisfying consequences).</td></tr><tr><td>58</td><td>A. Both Assertion and Reason are true, and Reason correctly explains Assertion.</td><td>Gestalt psychology rejected structuralism&#x27;s reductionist approach of breaking consciousness into isolated elements. Gestalt theorists emphasized that psychological phenomena must be understood as organized wholes, where relationships among parts create emergent properties not present in individual elements (&quot;the whole is greater than sum of parts&quot;).</td></tr><tr><td>59</td><td>C. 1-c, 2-b, 3-a</td><td>Mary Main&#x27;s Adult Attachment Interview classifications correspond to infant attachment styles: Dismissing adults (deactivating attachment strategies) correspond to avoidant infants; Enmeshed/Preoccupied adults (hyperactivating strategies) correspond to resistant infants; Secure adults correspond to secure infants, showing continuity across lifespan.</td></tr><tr><td>60</td><td>B. Internal working model</td><td>Bowlby proposed that repeated attachment experiences form internal working models—mental representations of caregiver availability and responsiveness that guide expectations and attachment behaviors. These cognitive-affective schemas influence relationship patterns throughout life and are central to attachment theory.</td></tr><tr><td>61</td><td>B. Client-centered psychotherapy</td><td>Carl Rogers originally termed his therapeutic approach &quot;client-centered psychotherapy&quot; (later &quot;person-centered&quot;), emphasizing the therapist&#x27;s provision of unconditional positive regard, empathy, and genuineness to facilitate client self-actualization and growth. This contrasted with directive, expert-oriented therapies.</td></tr><tr><td>62</td><td>D. &quot;I value you for who you are, independent of what you provide for me&quot;.</td><td>Maslow distinguished D-love (deficiency love—needing someone to fill emotional needs) from B-love (being love—valuing someone for their inherent being, independent of what they provide). B-love is unselfish, appreciative, and non-possessive, characteristic of self-actualized individuals.</td></tr><tr><td>63</td><td>A. Hering</td><td>Ewald Hering proposed the opponent-process theory of color vision, suggesting color perception involves three opponent pairs: red-green, blue-yellow, and black-white. This explained color afterimages and color blindness patterns better than Helmholtz&#x27;s trichromatic theory alone. Modern research shows both theories are correct at different processing levels.</td></tr><tr><td>64</td><td>A. 1-b, 2-c, 3-d, 4-a</td><td>Edward Thorndike formulated the Law of Effect; John Watson conducted the Little Albert classical conditioning experiment demonstrating learned fear; Clark Hull developed drive-reduction theory of motivation; Konrad Lorenz conducted natural-environment studies of animal behavior (ethology), especially imprinting in geese.</td></tr><tr><td>65</td><td>B. Fixed ratio</td><td>A fixed ratio (FR) schedule delivers reinforcement after a set number of responses. Completing exactly every tenth task before receiving reinforcement exemplifies FR-10. Fixed ratio schedules produce high, steady response rates with brief post-reinforcement pauses. Variable schedules involve unpredictable numbers or intervals.</td></tr><tr><td>66</td><td>A. Flooding</td><td>Flooding involves prolonged, intense exposure to the feared stimulus (cats) without the originally feared outcome occurring, leading to extinction of the fear response. Unlike systematic desensitization (gradual exposure with relaxation), flooding is rapid and intense. Implosion uses imagined exposure; token economy uses reinforcement.</td></tr><tr><td>67</td><td>B. Stereotyped behavior sequences that do not have to be learned</td><td>Fixed-action patterns are innate, stereotyped behavioral sequences triggered by specific stimuli (sign stimuli) that occur without learning. Examples include egg-retrieval in geese, web-spinning in spiders. These differ from learned behaviors acquired through conditioning or observation.</td></tr><tr><td>68</td><td>C. Retrieval</td><td>When the student produces the telephone number when asked, this demonstrates retrieval—accessing and bringing stored information into conscious awareness for use. Encoding involves initially processing information; storage involves maintaining it over time; consolidation stabilizes memories neurologically.</td></tr><tr><td>69</td><td>A. The smallest meaningful unit of language</td><td>A morpheme is the smallest linguistic unit carrying meaning (e.g., &quot;un-&quot; meaning not, &quot;happy&quot; meaning joyful, &quot;-ness&quot; meaning state of). Morphemes combine to form words. Phonemes are smallest sound units; syntax is grammatical arrangement; semantics is overall meaning.</td></tr><tr><td>70</td><td>C. Spontaneous recovery</td><td>Spontaneous recovery—the reappearance of an extinguished conditioned response after a rest period without further conditioning—directly contradicts the claim that extinction permanently eliminates the CR. This shows extinction suppresses rather than erases the learned association, which can reemerge.</td></tr><tr><td>71</td><td>B. A general factor underlying individual differences in intelligence</td><td>Spearman&#x27;s g factor (general intelligence) is a broad mental capacity influencing performance across diverse cognitive tasks. Using factor analysis, Spearman found positive correlations among different ability tests, proposing g as the common underlying factor plus specific abilities (s) for particular tasks.</td></tr><tr><td>72</td><td>C. Declarative memory — information that can be consciously recalled</td><td>Declarative (explicit) memory involves information that can be consciously recalled and declared (facts, events). Procedural memory involves skills/procedures; semantic memory involves factual knowledge; sensory memory is brief initial registration. Option C correctly matches the memory type with its definition.</td></tr><tr><td>73</td><td>B. Melzack and Wall</td><td>Ronald Melzack and Patrick Wall proposed the gate control theory of pain in 1965, suggesting spinal cord mechanisms can modulate pain signals before reaching the brain. Psychological factors can &quot;open&quot; or &quot;close&quot; the gate, explaining why pain perception varies with attention, emotion, and context.</td></tr><tr><td>74</td><td>A. More specific than g but more general than s</td><td>L.L. Thurstone identified seven primary mental abilities (verbal comprehension, word fluency, number, space, associative memory, perceptual speed, reasoning) that are more specific than Spearman&#x27;s general factor (g) but more general than task-specific factors (s), representing intermediate-level abilities.</td></tr><tr><td>75</td><td>A. Anxiety and deep relaxation cannot be experienced simultaneously</td><td>Systematic desensitization, developed by Joseph Wolpe, is based on reciprocal inhibition—the principle that anxiety and deep relaxation are incompatible states that cannot coexist. By pairing relaxation with gradually intensifying anxiety-provoking stimuli, the relaxation response inhibits and replaces the anxiety response.</td></tr><tr><td>76</td><td>A. Time-out</td><td>Time-out involves temporarily removing a person from a reinforcing environment immediately after undesirable behavior, thereby reducing access to positive reinforcement (like staff attention) that maintained the behavior. This differs from systematic desensitization (anxiety treatment), aversion therapy, or shaping (reinforcing successive approximations).</td></tr><tr><td>77</td><td>B. Verbal and nonverbal/imagery-based codes</td><td>Allan Paivio&#x27;s dual-code hypothesis proposes that information can be represented through two distinct coding systems: verbal (linguistic, symbolic) and nonverbal/imagery-based (visual, concrete). This explains why concrete words (easily imaged) are remembered better than abstract words.</td></tr><tr><td>78</td><td>A. Robert Sternberg</td><td>Robert Sternberg proposed the triarchic theory of intelligence comprising three aspects: analytical (problem-solving), creative (dealing with novelty), and practical (adapting to real-world demands). This contrasts with Gardner&#x27;s multiple intelligences, Cattell&#x27;s fluid/crystallized theory, and Spearman&#x27;s g factor.</td></tr><tr><td>79</td><td>A. 1-b, 2-d, 3-a, 4-c</td><td>Acquisition is learning the CS-UCS association; Extinction occurs when CS is presented repeatedly without UCS, weakening the CR; Spontaneous recovery is reappearance of CR after rest following extinction; Generalization occurs when similar stimuli to the CS also produce the CR. These are fundamental classical conditioning phenomena.</td></tr><tr><td>80</td><td>A. Signal detection theory</td><td>Signal detection theory analyzes performance in detecting weak signals embedded in noise using measures like hits, misses, false alarms, and correct rejections, often visualized with ROC (receiver operating characteristic) curves. This framework separates sensory sensitivity from response bias in perceptual decision-making.</td></tr><tr><td>81</td><td>B. Reinforcement increases behavior, whereas punishment decreases behavior</td><td>The fundamental distinction is functional: reinforcement (positive or negative) always increases the future frequency of a behavior, while punishment (positive or negative) always decreases it. This definitional difference is more important than whether rewards or aversive stimuli are involved.</td></tr><tr><td>82</td><td>A. Phoneme → morpheme → syntax → semantics → pragmatics</td><td>This sequence represents language organization from smallest to largest units: phonemes (sounds) combine into morphemes (meaningful units), which arrange via syntax (grammar) to create semantics (meaning), used within pragmatics (social context). This reflects the hierarchical structure of language.</td></tr><tr><td>83</td><td>B. Availability heuristic</td><td>The K-word problem error (overestimating words starting with K vs. having K as third letter) is explained by the availability heuristic—judging frequency/probability based on how easily examples come to mind. Words starting with K are more cognitively available, leading to overestimation despite more words having K in third position.</td></tr><tr><td>84</td><td>A. Whorfian hypothesis</td><td>The Whorfian hypothesis (linguistic relativity) proposes that language influences thought and perception—differences in linguistic categories available to speakers are associated with differences in how they conceptualize experience. This suggests language shapes cognition, though the strong deterministic version is largely discredited. simplypsychology+3</td></tr><tr><td>85</td><td>A. Linguistic, logical-mathematical, spatial, musical, bodily-kinesthetic, interpersonal, and intrapersonal</td><td>Howard Gardner&#x27;s theory of multiple intelligences originally identified seven distinct intelligences: linguistic, logical-mathematical, spatial, musical, bodily-kinesthetic, interpersonal (understanding others), and intrapersonal (understanding self). Later he added naturalistic and considered existential intelligence. psychology+3</td></tr><tr><td>86</td><td>A. Both Assertion and Reason are true, and Reason correctly explains Assertion.</td><td>Levels-of-processing theory (Craik &amp; Lockhart) proposes that deeper, more meaningful processing (semantic, elaborative) leads to better memory than shallow processing (structural, phonemic). The reason correctly explains why deep processing produces superior retention—encoding quality determines later retrievability. completeera+3</td></tr><tr><td>87</td><td>B. Clustering</td><td>When a participant recalls words grouped by category (flowers together, animals together) despite random presentation, this demonstrates clustering—organizing information during recall based on semantic categories. This shows how memory is reconstructive and influenced by organizational strategies, not just passive storage. resolve.cambridge+3</td></tr><tr><td>88</td><td>B. Quickly grasp relationships in novel situations and make correct deductions</td><td>Fluid intelligence involves reasoning, problem-solving, and adapting to novel situations independent of acquired knowledge. It includes abilities like identifying patterns, solving new problems, and making deductions. This contrasts with crystallized intelligence, which involves using learned knowledge and experience. resolve.cambridge+3</td></tr><tr><td>89</td><td>B. Availability heuristic</td><td>Choosing a restaurant because memorable experiences immediately come to mind exemplifies the availability heuristic—judging likelihood or value based on how easily examples are retrieved from memory. Vivid, recent, or emotionally salient memories are more available and disproportionately influence decisions. resolve.cambridge+3</td></tr><tr><td>90</td><td>A. Gibson and Walk</td><td>The visual cliff apparatus, developed by Eleanor Gibson and Richard Walk, consists of a transparent surface with an apparent drop beneath part, used to test depth perception in infants and animals. Their research showed that depth perception emerges early and may be partly innate, not solely learned.</td></tr><tr><td>91</td><td>B. Behavior and its consequences</td><td>Operant conditioning, developed by B.F. Skinner building on Thorndike&#x27;s Law of Effect, is based on learning associations between behaviors and their consequences (reinforcement or punishment). Behaviors followed by satisfying consequences increase; those followed by unpleasant consequences decrease.</td></tr><tr><td>92</td><td>C. X = recall; Y = recognition</td><td>Participant X writing down studied words demonstrates recall—retrieving information without external cues. Participant Y identifying whether shown words appeared on the list demonstrates recognition—identifying previously encountered information when presented. Recognition is typically easier than recall.</td></tr><tr><td>93</td><td>B. Operant conditioning</td><td>Thorndike&#x27;s Law of Effect (behaviors followed by satisfying consequences are strengthened) directly formed the basis for Skinner&#x27;s operant conditioning theory. Skinner extended this principle, systematically studying how reinforcement and punishment shape voluntary behavior through consequences.</td></tr><tr><td>94</td><td>C. Unconditioned stimulus</td><td>In Pavlov&#x27;s classical conditioning, food powder presented before conditioning is the unconditioned stimulus (UCS) because it naturally and automatically elicits salivation (unconditioned response) without prior learning. The bell becomes the conditioned stimulus after pairing with food.</td></tr><tr><td>95</td><td>A. Structuralism → functionalism, behaviorism, and Gestalt psychology</td><td>This sequence represents the historical transition in early psychology: Wundt and Titchener&#x27;s structuralism (analyzing consciousness into elements) gave way to functionalism (James—mental processes&#x27; functions), behaviorism (Watson, Skinner—observable behavior), and Gestalt psychology (Wertheimer—organized wholes).</td></tr><tr><td>96</td><td>C. Structuralism</td><td>Asking participants to describe immediate conscious experiences while viewing stimuli exemplifies structuralism&#x27;s introspective method. Structuralists trained observers to report basic elements of consciousness (sensations, feelings, images) in response to standardized stimuli, aiming to analyze mental structure.</td></tr><tr><td>97</td><td>C. Retrieval difficulty</td><td>When a student cannot produce a learned name despite feeling it&#x27;s accessible (tip-of-the-tongue phenomenon), this illustrates retrieval difficulty—temporary inability to access stored information despite successful encoding and storage. The information exists in memory but cannot be retrieved at that moment.</td></tr><tr><td>98</td><td>B. Superior memory for the initial items in a list</td><td>The primacy effect refers to better memory for items at the beginning of a list, attributed to greater rehearsal and transfer to long-term memory. The recency effect shows better memory for final items (still in short-term memory). Both contribute to the serial position curve in free recall.</td></tr><tr><td>99</td><td>C. 7 ± 2 chunks</td><td>George Miller&#x27;s classic 1956 paper &quot;The Magical Number Seven, Plus or Minus Two&quot; proposed that short-term memory capacity is approximately 7 ± 2 chunks (meaningful units). This finding became foundational in cognitive psychology, though later research suggests capacity may be closer to 4 ± 1 chunks for some materials.</td></tr><tr><td>100</td><td>B. Elaborative rehearsal</td><td>Elaborative rehearsal—connecting new information to existing knowledge through meaning, associations, and deeper processing—is most effective for transferring information into long-term memory. Maintenance rehearsal (simple repetition) keeps information in short-term memory but doesn&#x27;t ensure long-term retention.</td></tr></tbody></table></div>", "options": ["Maintenance rehearsal", "Elaborative rehearsal", "Recency rehearsal", "Sensory rehearsal"], "correctAnswer": 1, "subject": "Cognitive Psychology", "subtopic": "", "explanation": "Elaborative rehearsal—connecting new information to existing knowledge through meaning, associations, and deeper processing—is most effective for transferring information into long-term memory. Maintenance rehearsal (simple repetition) keeps information in short-term memory but doesn't ensure long-term retention.", "difficulty": "Medium"}];
